import {composeShot} from './shot-contract.js';
import {prepareMethods} from './method-catalog.js';
import {generateBoard,boardQualityMarkup,bindBoardQuality,showBoardReport} from './studio-board.js';
import {C,$,save,on,modal,esc,toast,wait,methodMarkup,bindMethods} from './studio-ui.js';
import {clone,uid,changed,logJob,taskSnapshot,reviewScript,invalidateChain,setGeneration,hub} from './workflow-store.js';
export function prepareWorkbenches(){const s=C.s;s.director??={open:{},chats:{},drafts:{},floating:{}};s.boardMethod??={mode:'skill',name:'分镜导演 Skill',text:s.defaults.storyboard,version:1};s.generation??={aspect:s.aspect||'',resolution:s.resolution||hub().config.generationDefaults?.resolution||'1080P',model:s.models.video?.name||'演示视频模型'};if(!s.generation.aspect){const d=hub().config.generationDefaults;setGeneration(s,{aspect:d?.aspect||'9:16',resolution:s.generation.resolution||d?.resolution||'1080P',model:s.generation.model||d?.model||'演示视频模型'});s.specInherited=true;}prepareMethods(s,hub());s.projectElements??=[];for(const sh of s.shots){if(sh.video?.snapshot?.style&&JSON.stringify(sh.video.snapshot.style)!==JSON.stringify(composeShot(s,sh).style)){invalidateChain(s,s.shots.indexOf(sh));sh.videoStale=true;}sh.dialogues??=[{id:uid('line'),speaker:sh.speaker||'旁白',emotion:sh.emotion||'自然',text:sh.dialogue||'',voice:'默认音色'}];sh.dialogue=dialogueText(sh);}}
export function dialogueText(sh){return sh.dialogues.map(d=>`${d.speaker}：${d.text}`).join('\n')}
export function dialogueMarkup(sh,i){return `<div class="dialogue-lines">${sh.dialogues.map((d,n)=>`<div class="dialogue-line"><div class="dialogue-line-head"><input aria-label="镜头${i+1}台词${n+1}角色" data-line-speaker="${d.id}" value="${esc(d.speaker)}"><select aria-label="镜头${i+1}台词${n+1}情绪" data-line-emotion="${d.id}">${['自然','克制','喜悦','愤怒','悲伤','迟疑'].map(e=>`<option ${e===d.emotion?'selected':''}>${e}</option>`).join('')}</select><button class="text-button" data-delete-line="${d.id}" aria-label="删除镜头${i+1}台词${n+1}" ${sh.dialogues.length===1?'disabled':''}>×</button></div><textarea aria-label="镜头${i+1}台词${n+1}正文" data-line-text="${d.id}">${esc(d.text)}</textarea><div class="line-audio-tools"><button class="text-button" data-line-tts="${d.id}" ${!d.text.trim()?'disabled':''}>${d.audio?'重新配音':'TTS 生成'}</button><span>${d.audio?(d.audio.stale?'待更新':'示例就绪'):'未生成'}</span>${d.audio?`<button class="text-button" data-line-listen="${d.id}" aria-label="试听该段台词">▷</button>`:''}</div></div>`).join('')}<button class="text-button" data-add-line="${sh.id}">＋ 添加台词</button></div>`}
export function bindDialogues(){const s=C.s;function locate(id){for(const sh of s.shots){const line=sh.dialogues.find(l=>l.id===id);if(line)return{sh,line}}}document.querySelectorAll('[data-line-tts]').forEach(b=>b.onclick=async()=>{const {sh}=locate(b.dataset.lineTts);b.disabled=true;await generateSpeech(sh,b.dataset.lineTts);C.render()});document.querySelectorAll('[data-line-listen]').forEach(b=>b.onclick=()=>{const {line}=locate(b.dataset.lineListen);if(!window.speechSynthesis)return toast('当前浏览器不支持朗读');speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(line.text));toast('浏览器朗读示例，非真实TTS文件')});function dirty(sh){sh.dialogue=dialogueText(sh);sh.version++;if(sh.audio)sh.audio.stale=true;changed(s,s.shots.indexOf(sh));save()}
for(const [attr,key] of [['text','text'],['speaker','speaker'],['emotion','emotion']])document.querySelectorAll(`[data-line-${attr}]`).forEach(e=>e.onchange=()=>{const{sh,line}=locate(e.dataset['line'+attr[0].toUpperCase()+attr.slice(1)]);line[key]=e.value;if(line.audio)line.audio.stale=true;dirty(sh);C.render()});document.querySelectorAll('[data-add-line]').forEach(b=>b.onclick=()=>{const sh=s.shots.find(sh=>sh.id===b.dataset.addLine);sh.dialogues.push({id:uid('line'),speaker:'角色',text:'',emotion:'自然',voice:'默认音色'});dirty(sh);C.render()});document.querySelectorAll('[data-delete-line]').forEach(b=>b.onclick=()=>{const{sh,line}=locate(b.dataset.deleteLine);sh.dialogues=sh.dialogues.filter(l=>l.id!==line.id);dirty(sh);C.render()});}
export async function generateSpeech(sh,lineId=null){const s=C.s;const selected=sh.dialogues.filter(d=>!lineId||d.id===lineId);if(!selected.length||selected.some(d=>!d.text.trim())){toast('请补齐每段台词再配音');return false}const frozen=clone(selected),snapshot=taskSnapshot(s,'voice',{shotId:sh.id,dialogues:clone(sh.dialogues.map(({audio,...d})=>d))});for(const d of frozen){const source=sh.dialogues.find(x=>x.id===d.id);if(!source)continue;const result={id:uid('tts'),kind:'demo',text:d.text,speaker:d.speaker,voice:d.voice,emotion:d.emotion,stale:false};await wait(120);source.audio={...result,stale:source.text!==d.text||source.speaker!==d.speaker||source.voice!==d.voice||source.emotion!==d.emotion};logJob(s,'voice',{...result,snapshot:{...snapshot,lineId:d.id,dialogue:d.text,voice:d.voice,emotion:d.emotion}})}sh.audio={id:uid('tts-track'),kind:'demo',text:dialogueText(sh),segments:clone(sh.dialogues.map(d=>d.audio)),stale:sh.dialogues.some(d=>!d.audio||d.audio.stale)};save();return true;}
function target(page){const s=C.s;if(page==='creation')return{id:'idea',text:s.idea};if(page==='story'){const t=s.topics.find(t=>t.id===s.storyFocus)||s.topics[(s.storyPage||0)*3];return t?{id:t.id,text:t.text}:null}if(page==='script')return s.scriptDraft?{id:s.scriptDraft.id,text:s.scriptDraft.text}:null;const sh=s.shots.find(sh=>sh.id===s.directorShot)||s.shots[0];return sh?{id:sh.id,text:sh.prompt}:null}
function proposal(page,text,instruction){if(page==='creation')return `${text.replace(/。$/,'')}；${instruction.includes('双反转')?'他先误以为帮助来自陌生人，后来才发现对方曾被自己帮助，最终选择把善意传给下一个人。':instruction.includes('目标')?'主角必须在天亮前作出一次无法撤回的选择。':'一封被隐瞒的信改变了人物的判断，让原本简单的目标变得两难。'}`;if(page==='story')return `${text}\n\n${instruction.includes('动机')?'他终于说出了迟迟没有行动的原因：害怕承认自己仍然需要被帮助。':instruction.includes('情感')?'两人各自坚持着不同的善意，话到嘴边又停下，直到一个小小的动作替他们完成了和解。':'结尾不再解释情感，而是让主角以一个克制的动作回应开场。'}\n[演示修订要求：${instruction}]`;if(page==='script')return `${text}\n\n【导演修订示例】${instruction}。表演留出停顿，以目光和动作衔接情绪，保留原有事件与人物关系。`;return `${text}\n镜头调整示例：${instruction}。保持轴线、角色朝向和全部图片引用，动作衔接连续。`}
export function mountDirector(page){if(!['story','script','storyboard'].includes(page))return;const s=C.s;prepareWorkbenches();document.querySelector('.idea-note')?.remove();document.querySelector('#story-assistant')?.remove();const main=document.querySelector('.page');const layout=document.createElement('div');layout.className='director-layout';layout.id='director-layout';const content=document.createElement('div');content.className='director-main';for(const child of [...main.children])if(!child.matches('.studio-steps,.page-heading,dialog'))content.append(child);layout.append(content);main.append(layout);const open=s.director.open[page]!==false;layout.classList.toggle('director-collapsed',!open);const current=target(page),key=`${page}:${current?.id||'empty'}`,chats=s.director.chats[key]||[];const names={creation:'创意',story:'故事',script:'剧本',storyboard:'分镜'},suggestions={creation:['推荐故事结构：双反转','强化核心冲突','明确主角目标'],story:['强化角色动机','强化情感冲突','优化结尾'],script:['优化场景节奏','让台词更自然','强化人物行动'],storyboard:['优化镜头提示词','强化动作连续性','调整画面情绪']};const methodKey=page==='creation'||page==='story'?'writingMethod':page==='script'?'scriptMethod':'boardMethod';const aside=document.createElement('aside');aside.id='director-panel';aside.className='director-panel panel';if(open&&s.director.floating[page]){aside.classList.add('director-floating');layout.classList.add('director-undocked')};aside.innerHTML=`${open?`<div class="panel-header"><h2>AI 导演助手</h2><div><button class="text-button" id="float-director" aria-label="${s.director.floating[page]?'固定到右侧':'弹出导演助手'}">${s.director.floating[page]?'固定':'弹出'}</button><button class="text-button" id="toggle-director" aria-label="收起AI导演助手">收起 ›</button></div></div><p class="helper">一起讨论${names[page]}，满意后再采用新版。</p>${page==='storyboard'&&s.shots.length?`<label class="field">当前镜头<select id="director-shot">${s.shots.map((sh,i)=>`<option value="${sh.id}" ${sh.id===current?.id?'selected':''}>镜头 ${i+1}</option>`).join('')}</select></label>`:''}<div class="director-messages" role="log" aria-label="${names[page]}对话"><div class="director-message"><strong>${names[page]}建议</strong><div class="director-suggestions">${suggestions[page].map(t=>`<button class="button" data-director-suggest="${t}" ${!current?'disabled':''}>${t}</button>`).join('')}</div></div>${chats.map((m,i)=>`<div class="director-message ${m.role==='user'?'from-user':''}"><small>${m.role==='user'?'你':'AI 导演 · 演示'}</small><p>${esc(m.text)}</p>${m.proposal?`<button class="button" data-adopt="${i}" ${m.adopted?'disabled':''}>${m.adopted?'已采用':'采用此版'+names[page]}</button>`:''}</div>`).join('')}</div>${['script','storyboard'].includes(page)?`<button class="button review-entry" id="director-review" ${!current?'disabled':''}>${names[page]}质检</button><div id="director-quality">${page==='storyboard'?boardQualityMarkup():''}</div>`:''}<label class="field director-composer">你的想法<textarea id="director-input" placeholder="描述你的修改要求…" ${!current?'disabled':''}>${esc(s.director.drafts[key]||'')}</textarea></label><div class="director-generation-row">${page==='creation'?'':methodMarkup(methodKey)}<button class="button primary" id="director-send" ${(page==='storyboard'?!s.final:!current)?'disabled':''}>${page==='storyboard'?'生成分镜表':'生成建议版'}</button></div><small class="helper">原型使用示例响应，尚未连接真实 AI。</small>`:'<button class="director-reopen" id="toggle-director" aria-label="展开AI导演助手">AI 导演 ‹</button>'}`;layout.append(aside);if(page==='script'&&$('script-quality')){const q=$('script-quality');(open?$('director-quality'):aside).append(q);q.hidden=!open;q.classList.remove('panel');}on('toggle-director',()=>{s.director.open[page]=!open;save();C.render()});on('float-director',()=>{s.director.floating[page]=!s.director.floating[page];save();C.render()});if(!open)return;bindMethods(aside);if(page==='storyboard')bindBoardQuality();
if($('director-shot'))$('director-shot').onchange=e=>{s.directorShot=e.target.value;save();C.render()};$('director-input').oninput=e=>{s.director.drafts[key]=e.target.value;save()};function send(instruction){if(!current||!instruction.trim())return toast('请输入修改要求');const fresh=target(page);const response=proposal(page,fresh.text,instruction);s.director.chats[key]??=[];s.director.chats[key].push({role:'user',text:instruction},{role:'assistant',text:response,proposal:true,baseText:fresh.text,targetId:fresh.id,adopted:false});s.director.drafts[key]='';logJob(s,{creation:'ideaRefine',story:'novelRevision',script:'scriptRefine',storyboard:'boardRefine'}[page],{instruction,source:fresh,proposal:response});save();C.render()}
on('director-send',()=>{if(page==='storyboard'){const instruction=$('director-input').value;s.director.chats[key]??=[];s.director.chats[key].push({role:'user',text:instruction||'按当前分镜方法生成分镜表'},{role:'assistant',text:'已按当前方法刷新分镜表，旧版已归档。'});s.director.drafts[key]='';generateBoard(instruction);}else send($('director-input').value)});document.querySelectorAll('[data-director-suggest]').forEach(b=>b.onclick=()=>send(b.dataset.directorSuggest));document.querySelectorAll('[data-adopt]').forEach(b=>b.onclick=()=>{const m=s.director.chats[key][+b.dataset.adopt],now=target(page);if(!now||now.id!==m.targetId||now.text!==m.baseText)return toast('当前内容已变化，请基于最新版重新生成建议');if(page==='creation'){s.ideaHistory??=[];s.ideaHistory.push(s.idea);s.idea=m.text;}else if(page==='story'){const t=s.topics.find(t=>t.id===now.id);t.versions??=[];t.versions.push({text:t.text,version:t.version});t.text=m.text;t.version++;if(s.selectedNovel?.id===t.id){s.final=null;s.scriptReport=null;s.boardConfirmed=0;}}else if(page==='script'){s.scriptHistory.push(clone(s.scriptDraft));s.scriptDraft.text=m.text;s.scriptDraft.version++;s.scriptReport=null;s.final=null;s.boardConfirmed=0;}else{const sh=s.shots.find(sh=>sh.id===now.id);s.history.push({boardVersion:s.boardVersion,scriptId:s.boardScriptId,shots:clone(s.shots)});sh.prompt=m.text;sh.version++;changed(s,s.shots.indexOf(sh));}m.adopted=true;save();C.render();toast('新版已采用，旧版已保留')});on('director-review',()=>{if(page==='script')$('recheck-script')?.click();else showBoardReport()});}
